    best_coilable = best_design['coilable']
    
    # Count feasible designs
    n_feasible = len(feasible)
    n_total = len(data)
    
    # Compute statistics on the feasible set
    max_sigma_crit_feasible = feasible['sigma_crit'].max()
    
