    # Primary assertion: verify the headline number (93.409 kPa)
    tolerance = 0.01
    if abs(best_sigma_crit - 93.409) < tolerance:
        print(f"\n✓ REPLICATED: Best coilable==1 design sigma_crit = {best_sigma_crit:.3f} kPa")
        status = 0
    else:
        print(f"\n⚠ WARNING: Best sigma_crit {best_sigma_crit:.3f} kPa")
